<?php
namespace App\Http\Controllers;use App\Models\Product;use Illuminate\Http\Request;
class CartController extends Controller { private function items(){return session('cart',[]);} public function add(Request $r,Product $product){abort_if($product->stock_status!=='in_stock',422);$q=max(1,(int)$r->input('quantity',1));$c=$this->items();$c[$product->id]=['id'=>$product->id,'title'=>$product->title,'price'=>(float)$product->price,'unit'=>$product->unit,'quantity'=>($c[$product->id]['quantity']??0)+$q];session(['cart'=>$c]);return back()->with('status',__('Added to cart.'));} public function index(){return view('cart.index',['items'=>$this->items(),'whatsAppNumber'=>preg_replace('/\D/','',config('deshibazaar.whatsapp_inquiry_number'))]);} public function update(Request $r){$c=$this->items();foreach($r->input('quantities',[]) as $id=>$q){if(isset($c[$id])){$q=(int)$q;$q>0?$c[$id]['quantity']=$q:unset($c[$id]);}}session(['cart'=>$c]);return back()->with('status',__('Cart updated.'));} public function destroy(int $id){$c=$this->items();unset($c[$id]);session(['cart'=>$c]);return back();}}
